WITH department_summary AS (SELECT dept_id, ROUND((100 * SUM(CASE WHEN level = 'L3' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_l3, COUNT(CASE WHEN job_title = 'Manager' THEN 1 END) AS manager_count FROM employees GROUP BY dept_id) SELECT d.id, d.budget, d.dept_name, ds.pct_l3, ds.manager_count FROM departments d LEFT JOIN department_summary ds ON d.id = ds.dept_id WHERE ds.pct_l3 >= 26;
